window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-5e55ae14970111f8"]={"versions": [{"id": "FIG-5e55ae14970111f8", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm der AUTOSAR Timing Extensions (Metamodell-Ausschnitt zur Beschreibung von Ereignisketten). Es spezifiziert die strukturellen Beziehungen und Vererbungsstrukturen zwischen Ereignisketten (<code>TimingDescriptionEventChain</code>) und den zugehörigen Timing-Ereignissen (<code>TimingDescriptionEvent</code>) im Rahmen der abstrakten Oberklasse <code>TimingDescription</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>Identifiable</code>: Abstrakte Basiskonzept-Klasse, deklariert als Metaklasse/Generalisierungsebene über <code>TimingDescription</code>.\n</li><li><code>TimingDescription</code>: Abstrakte Metaklasse (kursiv dargestellt), erbt von <code>Identifiable</code> und dient als gemeinsame Basis für <code>TimingDescriptionEventChain</code> und <code>TimingDescriptionEvent</code>.\n</li><li><code>TimingDescriptionEventChain</code>: Konkrete Metaklasse, erbt von <code>TimingDescription</code>. Weist ein separates Fach für <code>constraints</code> auf.\n<ul class=\"fig-list\"><li>Assoziation <code>+stimulus</code> (Kardinalität <code>1</code>): Gerichtet zu <code>TimingDescriptionEvent</code>, definiert das auslösende Startereignis der Kette.\n</li><li>Assoziation <code>+response</code> (Kardinalität <code>1</code>): Gerichtet zu <code>TimingDescriptionEvent</code>, definiert das abschließende Folgeereignis der Kette.\n</li><li>Rekursive Assoziation <code>+segment</code> (Kardinalität <code>1..*</code>): Gerichtet auf sich selbst (<code>TimingDescriptionEventChain</code>), zur hierarchischen Zerlegung in Teilketten/Segmente.\n</li></ul>\n</li><li><code>TimingDescriptionEvent</code>: Abstrakte Metaklasse (kursiv dargestellt), erbt von <code>TimingDescription</code>. Zieltyp der Rollen <code>+stimulus</code> und <code>+response</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Ausführungsdynamik. Modelliert wird die Spezifikation eines zeitlichen Ursache-Wirkungs-Zusammenhangs: Ein definierter Stimulus (<code>+stimulus</code>) initiiert eine zeitlich nachverfolgbare Kette, die aus mindestens einem Segment (<code>+segment 1..*</code>) besteht und in einer eindeutigen Antwort (<code>+response</code>) terminiert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Für <code>TimingDescriptionEventChain</code> sind zwei formale Konsistenzbedingungen (OCL/Constraints) direkt im Klassendiagramm festgeschrieben:</p>\n<ol class=\"fig-list\"><li><code>{stimulus != response}</code>: Stimulus- und Response-Ereignis einer Ereigniskette müssen disjunkt sein.\n</li><li><code>{For each segment there exists at least one path (of segments) from the stimulus to the response.}</code>: Jedes referenzierte Segment muss auf mindestens einem zusammenhängenden Pfad vom Stimulus zur Response liegen.\n</li></ol>\n<p class=\"fig-p\">Beide Rollen <code>+stimulus</code> und <code>+response</code> sind obligatorisch (Multiplizität genau <code>1</code>). Eine Ereigniskette muss aus mindestens einem Segment bestehen (<code>1..*</code>).</p>"}, {"id": "FIG-4f9bc462f256993d", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm der AUTOSAR Timing Extensions (Metamodell-Ausschnitt zur Beschreibung von Ereignisketten). Es spezifiziert die strukturellen Beziehungen und Vererbungsstrukturen zwischen Ereignisketten (<code>TimingDescriptionEventChain</code>) und den zugehörigen Timing-Ereignissen (<code>TimingDescriptionEvent</code>) im Rahmen der abstrakten Oberklasse <code>TimingDescription</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>Identifiable</code>: Abstrakte Basiskonzept-Klasse, deklariert über <code>TimingDescription</code>.\n</li><li><code>TimingDescription</code>: Abstrakte Metaklasse (kursiv dargestellt), erbt von <code>Identifiable</code> und fungiert als Generalisierung von <code>TimingDescriptionEventChain</code> und <code>TimingDescriptionEvent</code>.\n</li><li><code>TimingDescriptionEventChain</code>: Konkrete Metaklasse, erbt von <code>TimingDescription</code>.\n<ul class=\"fig-list\"><li>Assoziation <code>+stimulus</code> (Kardinalität <code>1</code>): Gerichtet zu <code>TimingDescriptionEvent</code>.\n</li><li>Assoziation <code>+response</code> (Kardinalität <code>1</code>): Gerichtet zu <code>TimingDescriptionEvent</code>.\n</li><li>Rekursive Assoziation <code>+segment</code> (Kardinalität <code>1..*</code>): Gerichtet auf sich selbst (<code>TimingDescriptionEventChain</code>).\n</li></ul>\n</li><li><code>TimingDescriptionEvent</code>: Abstrakte Metaklasse (kursiv dargestellt), erbt von <code>TimingDescription</code>. Zieltyp für <code>+stimulus</code> und <code>+response</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Ausführungsdynamik. Modelliert wird die Spezifikation eines zeitlichen Ursache-Wirkungs-Zusammenhangs: Ein definierter Stimulus (<code>+stimulus</code>) initiiert eine zeitlich nachverfolgbare Kette, die aus mindestens einem Segment (<code>+segment 1..*</code>) besteht und in einer eindeutigen Antwort (<code>+response</code>) terminiert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die strukturelle Integrität der Ereigniskette erfordert genau ein Stimulus-Ereignis (<code>+stimulus 1</code>) und genau ein Response-Ereignis (<code>+response 1</code>). Die Zerlegung in Teilketten erfolgt über die obligatorische Segment-Assoziation mit einer Mindestanzahl von einem Segment (<code>+segment 1..*</code>). Zusätzliche Modellierungsbedingungen werden nicht mehr direkt im Diagrammfeld als <code>constraints</code> visualisiert, sondern über den begleitenden Spezifikationstext bzw. das AUTOSAR-Metamodell geregelt.</p>"}, {"id": "FIG-c95e0c627fdd8f3b", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm der AUTOSAR Timing Extensions (Metamodell-Ausschnitt zur Beschreibung von Ereignisketten). Es spezifiziert die strukturellen Beziehungen und Vererbungsstrukturen zwischen Ereignisketten (<code>TimingDescriptionEventChain</code>) und den zugehörigen Timing-Ereignissen (<code>TimingDescriptionEvent</code>) im Rahmen der abstrakten Oberklasse <code>TimingDescription</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>Identifiable</code>: Abstrakte Basiskonzept-Klasse, deklariert über <code>TimingDescription</code>.\n</li><li><code>TimingDescription</code>: Abstrakte Metaklasse (kursiv dargestellt), erbt von <code>Identifiable</code> und fungiert als Generalisierung von <code>TimingDescriptionEventChain</code> und <code>TimingDescriptionEvent</code>.\n</li><li><code>TimingDescriptionEventChain</code>: Konkrete Metaklasse, erbt von <code>TimingDescription</code>.\n<ul class=\"fig-list\"><li>Assoziation <code>+stimulus</code> (Kardinalität <code>1</code>): Gerichtet zu <code>TimingDescriptionEvent</code>.\n</li><li>Assoziation <code>+response</code> (Kardinalität <code>1</code>): Gerichtet zu <code>TimingDescriptionEvent</code>.\n</li><li>Rekursive Assoziation <code>+segment</code> (Kardinalität <code>1..*</code>): Gerichtet auf sich selbst (<code>TimingDescriptionEventChain</code>).\n</li></ul>\n</li><li><code>TimingDescriptionEvent</code>: Abstrakte Metaklasse (kursiv dargestellt), erbt von <code>TimingDescription</code>. Zieltyp für <code>+stimulus</code> und <code>+response</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Ausführungsdynamik. Modelliert wird die Spezifikation eines zeitlichen Ursache-Wirkungs-Zusammenhangs: Ein definierter Stimulus (<code>+stimulus</code>) initiiert eine zeitlich nachverfolgbare Kette, die aus mindestens einem Segment (<code>+segment 1..*</code>) besteht und in einer eindeutigen Antwort (<code>+response</code>) terminiert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die strukturelle Integrität der Ereigniskette erfordert genau ein Stimulus-Ereignis (<code>+stimulus 1</code>) und genau ein Response-Ereignis (<code>+response 1</code>). Die Zerlegung in Teilketten erfolgt über die obligatorische Segment-Assoziation mit einer Mindestanzahl von einem Segment (<code>+segment 1..*</code>). Zusätzliche Modellierungsbedingungen werden nicht mehr direkt im Diagrammfeld als <code>constraints</code> visualisiert, sondern über den begleitenden Spezifikationstext bzw. das AUTOSAR-Metamodell geregelt.</p>"}, {"id": "FIG-337e8d89f333f981", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm der AUTOSAR Timing Extensions (Metamodell-Ausschnitt zur Beschreibung von Ereignisketten). Es spezifiziert die strukturellen Beziehungen und Vererbungsstrukturen zwischen Ereignisketten (<code>TimingDescriptionEventChain</code>) und den zugehörigen Timing-Ereignissen (<code>TimingDescriptionEvent</code>) im Rahmen der abstrakten Oberklasse <code>TimingDescription</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>Identifiable</code>: Abstrakte Basiskonzept-Klasse, deklariert über <code>TimingDescription</code>.\n</li><li><code>TimingDescription</code>: Abstrakte Metaklasse (kursiv dargestellt), erbt von <code>Identifiable</code> und fungiert als Generalisierung von <code>TimingDescriptionEventChain</code> und <code>TimingDescriptionEvent</code>.\n</li><li><code>TimingDescriptionEventChain</code>: Konkrete Metaklasse, erbt von <code>TimingDescription</code>.\n<ul class=\"fig-list\"><li>Assoziation <code>+stimulus</code> (Kardinalität <code>1</code>): Gerichtet zu <code>TimingDescriptionEvent</code>.\n</li><li>Assoziation <code>+response</code> (Kardinalität <code>1</code>): Gerichtet zu <code>TimingDescriptionEvent</code>.\n</li><li>Rekursive Assoziation <code>+segment</code> (Kardinalität <code>1..*</code>): Gerichtet auf sich selbst (<code>TimingDescriptionEventChain</code>).\n</li></ul>\n</li><li><code>TimingDescriptionEvent</code>: Abstrakte Metaklasse (kursiv dargestellt), erbt von <code>TimingDescription</code>. Zieltyp für <code>+stimulus</code> und <code>+response</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Ausführungsdynamik. Modelliert wird die Spezifikation eines zeitlichen Ursache-Wirkungs-Zusammenhangs: Ein definierter Stimulus (<code>+stimulus</code>) initiiert eine zeitlich nachverfolgbare Kette, die aus mindestens einem Segment (<code>+segment 1..*</code>) besteht und in einer eindeutigen Antwort (<code>+response</code>) terminiert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die strukturelle Integrität der Ereigniskette erfordert genau ein Stimulus-Ereignis (<code>+stimulus 1</code>) und genau ein Response-Ereignis (<code>+response 1</code>). Die Zerlegung in Teilketten erfolgt über die obligatorische Segment-Assoziation mit einer Mindestanzahl von einem Segment (<code>+segment 1..*</code>). Zusätzliche Modellierungsbedingungen werden nicht mehr direkt im Diagrammfeld als <code>constraints</code> visualisiert, sondern über den begleitenden Spezifikationstext bzw. das AUTOSAR-Metamodell geregelt.</p>"}, {"id": "FIG-3671e24dc1c9a3e2", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm der AUTOSAR Timing Extensions (Metamodell-Ausschnitt zur Beschreibung von Ereignisketten). Es spezifiziert die strukturellen Beziehungen und Vererbungsstrukturen zwischen Ereignisketten (<code>TimingDescriptionEventChain</code>) und den zugehörigen Timing-Ereignissen (<code>TimingDescriptionEvent</code>) im Rahmen der abstrakten Oberklasse <code>TimingDescription</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>Identifiable</code>: Abstrakte Basiskonzept-Klasse, deklariert über <code>TimingDescription</code>.\n</li><li><code>TimingDescription</code>: Abstrakte Metaklasse (kursiv dargestellt), erbt von <code>Identifiable</code> und fungiert als Generalisierung von <code>TimingDescriptionEventChain</code> und <code>TimingDescriptionEvent</code>.\n</li><li><code>TimingDescriptionEventChain</code>: Konkrete Metaklasse, erbt von <code>TimingDescription</code>.\n<ul class=\"fig-list\"><li>Assoziation <code>+stimulus</code> (Kardinalität <code>1</code>): Gerichtet zu <code>TimingDescriptionEvent</code>.\n</li><li>Assoziation <code>+response</code> (Kardinalität <code>1</code>): Gerichtet zu <code>TimingDescriptionEvent</code>.\n</li><li>Rekursive Assoziation <code>+segment</code> (Kardinalität <code>1..*</code>): Gerichtet auf sich selbst (<code>TimingDescriptionEventChain</code>).\n</li></ul>\n</li><li><code>TimingDescriptionEvent</code>: Abstrakte Metaklasse (kursiv dargestellt), erbt von <code>TimingDescription</code>. Zieltyp für <code>+stimulus</code> und <code>+response</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne Ausführungsdynamik. Modelliert wird die Spezifikation eines zeitlichen Ursache-Wirkungs-Zusammenhangs: Ein definierter Stimulus (<code>+stimulus</code>) initiiert eine zeitlich nachverfolgbare Kette, die aus mindestens einem Segment (<code>+segment 1..*</code>) besteht und in einer eindeutigen Antwort (<code>+response</code>) terminiert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die strukturelle Integrität der Ereigniskette erfordert genau ein Stimulus-Ereignis (<code>+stimulus 1</code>) und genau ein Response-Ereignis (<code>+response 1</code>). Die Zerlegung in Teilketten erfolgt über die obligatorische Segment-Assoziation mit einer Mindestanzahl von einem Segment (<code>+segment 1..*</code>). Zusätzliche Modellierungsbedingungen werden nicht mehr direkt im Diagrammfeld als <code>constraints</code> visualisiert, sondern über den begleitenden Spezifikationstext bzw. das AUTOSAR-Metamodell geregelt.</p>"}], "trans": [{"from": "FIG-5e55ae14970111f8", "to": "FIG-4f9bc462f256993d", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Klasse <code>TimingDescriptionEventChain</code>: Entfernung des separaten Faches <code>constraints</code> mit den expliziten Bedingungen <code>{stimulus != response}</code> und <code>{For each segment there exists at least one path (of segments) from the stimulus to the response.}</code>.\n</li><li>Farbschema und Schriftarten: Umstellung vom gelblichen Hintergrund auf das moderne AUTOSAR-Standardfarbschema (hellbeige Klassenfüllung) und angepasste Typografie.\n</li></ul>"}, {"from": "FIG-4f9bc462f256993d", "to": "FIG-c95e0c627fdd8f3b", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-c95e0c627fdd8f3b", "to": "FIG-337e8d89f333f981", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-337e8d89f333f981", "to": "FIG-3671e24dc1c9a3e2", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Assoziation <code>+segment</code>: Umbruch der Multiplizitätsbeschriftung von einzeilig <code>+segment 1..*</code> auf zweizeilig <code>+segment</code> / <code>1..*</code>.\n</li></ul>"}]};
